using System;using System.Reflection;using System.Collections;using Colossal.Mathematics;using Unity.Mathematics;
class Test52Passing {
 static Assembly a;static int n;static BindingFlags f=BindingFlags.Static|BindingFlags.NonPublic;
 static object Call(string t,string m,params object[] args)=>a.GetType("MedianGrassReplacement.Systems."+t).GetMethod(m,f).Invoke(null,args);
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);n++;}
 static Bezier4x3 Rail(float x,bool reverse){var p=new Bezier4x3(new float3(x,0,0),new float3(x,0,10),new float3(x,0,20),new float3(x,0,30));return reverse?MathUtils.Invert(p):p;}
 static void Main(){a=Assembly.LoadFrom("MedianGrassReplacement.dll");foreach(byte style in new byte[]{11,12}){bool yellow=style==12;byte center=(byte)Call("LineShapePolicy","Center",style),edge=(byte)Call("LineShapePolicy","Edge",style),divider=(byte)Call("LineShapePolicy","Divider",style);Check((bool)Call("CenterlineUpgradePolicy","YellowPaint",center,false)==yellow,"passing center color");Check((byte)Call("CenterlineUpgradePolicy","Pattern",center)==2,"passing center has two rails");Check((bool)Call("EdgeUpgradePolicy","Paired",edge),"passing edge has two rails");Check((bool)Call("EdgeUpgradePolicy","IsYellow",edge)==yellow,"passing edge color");Check((bool)Call("LaneDividerPolicy","Applied",divider)&&(bool)Call("LaneDividerPolicy","IsYellow",divider)==yellow,"passing divider state retained");}
 foreach(bool reverse in new[]{false,true})foreach(float inward in new[]{-10f,10f})foreach(bool swap in new[]{false,true}){var first=Rail(swap?.2f:-.2f,reverse);var second=Rail(swap?-.2f:.2f,reverse);var strokes=(IList)Call("PassingLinePolicy","Pair",first,second,new float3(inward,0,15));Check(strokes.Count>2,"one solid and multiple dash strokes");int solid=0,dashes=0;foreach(Bezier4x3 path in strokes){if(MathUtils.Length(path)>29){solid++;Check(math.sign(path.a.x)==-math.sign(inward),"solid rail faces outward independent of curve order/direction");}else{dashes++;Check(math.sign(path.a.x)==math.sign(inward),"dashes face inward independent of curve order/direction");}}Check(solid==1&&dashes>1,"paired passing line retains one solid rail");}
 foreach(string type in new[]{"TownRoadLane.Components.TRLSegmentLink","TownRoadLane.Components.TRLAreaLink","TownRoadLane.Components.MarkingLine","TownRoadLane.Components.MarkingOverride"})Check((bool)Call("ExternalPaintPolicy","IsUserPaint",type),"installed Town Lane identities protected");Check(!(bool)Call("ExternalPaintPolicy","IsUserPaint","OtherMod.Marking"),"no broad foreign-component guess");
 Console.WriteLine(n+" passing-line inward orientation, saved category values and observed manual-paint ownership checks passed.");}}
